#!/usr/bin/env node
// Task studio-skyways-destinations-20261106-170011-01 (lane AUDIO): runtime derivatives of the Skyways DESTINATIONS location sounds — the
// Clock Court's tower-movement TICK loop and its bell CHIME one-shot, the Starfall Arcade's ATTRACT-mode loop and the Aurora Picture
// House's PROJECTOR loop (audio/sfx.ts setLocationEmitters; world/skywaysDestAudio.ts places them). Generated by the lead through
// tools/audio-pipeline/soundlab_runner.py (one fsynced intent per POST; whole-second durations; SOUND_LAB_MAX_POSTS 4;
// /tmp/ll-soundlab.lock). This builder makes NO Sound Lab call: it edits the generated clips only (trim / fades / loop crossfade /
// level) and never creates sound.
//
// Inputs (read-only): $SOUND_LAB_AUDIO_DIR (default reference/tasks/skyways-destinations-20261106-170011/audio) {queue.json, raw/<id>.wav,
//   raw/<id>.sidecar.json}; each raw is verified against its runner sidecar SHA-256. Structural QC (envelope, quiet fraction, spectral
//   centroid, onsets; raw and derivative) is written privately to $SKYWAYS_AUDIO_QC (default <audio dir>/../qa/audio/structural-qc.json):
//   the worker cannot listen, the user taste-tests in game.
// Outputs: game/public/assets/audio/{skyways-clock-tick-loop,skyways-clock-chime,skyways-arcade-attract-loop,skyways-projector-loop}.mp3,
//   game/src/audio/manifest.skywaysDestinations.generated.ts (merged into bank.ts CLIP_MANIFEST),
//   game/public/assets/derivatives/audio-skyways-destinations.json (provenance, no URLs), the NOTICE / CREDITS block,
//   tools/release/public-inputs.json (only these paths).
//
// Ops: mono downmix (mean) -> the chime: trim [a, b] + cosine fades + peak -1 dBFS; the loops: an explicit window (set from the
//   structural QC below) -> equal-power crossfaded loop (lib/dsp makeLoop) with periodic decoder margins (withLoopMargins) + RMS
//   -20 dBFS under a -1 dBFS peak ceiling (the bed / flare-loop convention); the tick loop is BEAT-ALIGNED: it spans a whole number of
//   the take's own tick intervals (lib/dsp onsets), its seam and crossfade sit in the silence before a tick, so the seam interval is one
//   of the take's natural intervals -> MP3 (lamejs, mono, 64 kbps at 44.1 kHz). Cap: <= 140 KB of new runtime audio.
//
// Usage: SOUND_LAB_AUDIO_DIR=<dir> node tools/audio-pipeline/skyways-destinations-build.mjs [--dry-run]

import {createHash} from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {Mp3Encoder} from '@breezystack/lamejs';
import {readWav, toInt16} from './lib/wav.mjs';
import * as D from './lib/dsp.mjs';
import * as S from './lib/structural.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const TASK = 'studio-skyways-destinations-20261106-170011-01';
const TASK_REL = 'reference/tasks/skyways-destinations-20261106-170011';
const RAW_REL = `${TASK_REL}/audio`;
const AUDIO = process.env.SOUND_LAB_AUDIO_DIR || path.join(ROOT, RAW_REL), RAW = path.join(AUDIO, 'raw');
const QC_OUT = process.env.SKYWAYS_AUDIO_QC || path.join(AUDIO, '../qa/audio/structural-qc.json');
const OUT = path.join(ROOT, 'game/public/assets/audio');
const MANIFEST_TS = path.join(ROOT, 'game/src/audio/manifest.skywaysDestinations.generated.ts');
const PROV_REL = 'assets/derivatives/audio-skyways-destinations.json';
const NOTICE_REL = 'assets/audio/NOTICE.md', CREDITS_REL = 'assets/CREDITS.md';
const ALLOW = path.join(ROOT, 'tools/release/public-inputs.json');
const DRY = process.argv.includes('--dry-run');
const LOOP_MARGIN_S = 0.1;
const BYTE_CAP = 140 * 1024;
const sha = b => createHash('sha256').update(b).digest('hex');
const r3 = v => Math.round(v * 1000) / 1000;

/** The runtime cues of this build (game/src/audio/bank.ts CUES). */
export const CUES_SKYWAYS_DESTINATIONS = ['clockTick', 'clockChime', 'arcadeAttract', 'projectorRun'];

/**
 * Per clip (set after the structural QC of the raws; the full numbers are in the private structural-qc.json):
 *  - tick: 8 short bright clicks (45-50 ms, centroid 5.4-6.2 kHz, peak -7..-12 dB) every 0.491-0.511 s (one odd 0.541 s gap at the
 *    end) over a -61 dB floor: the loop = the 5 ticks from the 2nd (0.511 s) to the 7th (3.012 s), seam 0.15 s before a tick;
 *  - chime: silence to 0.30 s, a strike at 0.35 s (-17 dB, f0 ~170 Hz, centroid ~480 Hz), a second strike at 1.15 s (spectral-flux
 *    peak 0.53 of the first, a brightness jump), then one long ring decaying ~8 dB/s to -60 dB at 5.55 s (no clear third strike);
 *  - arcade: tonal bleeps / jingles (voiced 53 %, f0 ~1 kHz) with short gaps, active to 3.30 s, silence after: the loop runs from
 *    the gap at 0.10 s to the gap at 3.06 s (both crossfade spans in silence);
 *  - projector: a start transient at 0.33 s, a steady clatter -30/-31 dB (20 ms frames) from 0.5 s to 3.05 s (onsets every
 *    80-130 ms, centroid ~4.3 kHz), a stop burst at 3.1 s, silence from 3.4 s: the loop is cut from the steady span.
 */
const PLAN = {
  'clock-tick-01': {out: 'skyways-clock-tick-loop', kind: 'beatLoop', firstBeat: 1, beats: 5, pre: 0.15, xf: 0.08, kbps: 64},
  'clock-chime-01': {out: 'skyways-clock-chime', kind: 'oneshot', a: 0.32, b: 5.7, fadeIn: 0.01, fadeOut: 0.6, kbps: 64},
  'arcade-attract-01': {out: 'skyways-arcade-attract-loop', kind: 'loop', start: 0.1, len: 2.96, xf: 0.08, kbps: 64},
  'projector-run-01': {out: 'skyways-projector-loop', kind: 'loop', start: 0.55, len: 2.2, xf: 0.25, kbps: 64},
};

function encodeMp3(x, sr, kbps) {
  const enc = new Mp3Encoder(1, sr, kbps), ints = toInt16(x), parts = [];
  for (let i = 0; i < ints.length; i += 1152) { const b = enc.encodeBuffer(ints.subarray(i, i + 1152)); if (b.length) parts.push(Buffer.from(b)); }
  const end = enc.flush();
  if (end.length) parts.push(Buffer.from(end));
  return Buffer.concat(parts);
}

/** Structural numbers for the private QC record (no listening): level, envelope, quiet fraction, spectrum, onsets. */
function qcOf(x, sr) {
  const m = S.publicMetrics(S.structure(x, sr));
  const env = Array.from(D.envelope(x, Math.round(sr * 0.1)), v => Math.round(D.linToDb(v)));
  const on = D.onsets(x, sr, {riseDb: 6, floorDb: -30, minGapS: 0.08}).map(o => r3(o / sr));
  return {durationS: m.durationS, peakDbfs: m.peakDbfs, rmsDbfs: m.rmsDbfs, crestDb: m.crestDb, clippedFrac: m.clippedFrac, quietFrac: m.quietFrac,
    activeFrac: m.activeFrac, levelSpreadDb: m.levelSpreadDb, attack: m.attack, decay: m.decay, spectral: m.spectral,
    pitch: {voicedFrac: m.pitch.voicedFrac, f0MedianHz: m.pitch.f0MedianHz}, loudness: S.loudness(x, sr), levelPer100msDb: env, onsetsS: on};
}

/** Loop seam check: the sample step across the wrap vs the loop's median step, and the 10 ms level either side of it (dB). */
function seamOf(loop, sr) {
  const n = loop.length, w = Math.round(0.01 * sr), steps = [];
  for (let i = 1; i < n; i += 7) steps.push(Math.abs(loop[i] - loop[i - 1]));
  steps.sort((p, q) => p - q);
  const lvl = (a, b) => { let s = 0; for (let i = a; i < b; i++) s += loop[i] * loop[i]; return r3(D.linToDb(Math.sqrt(s / Math.max(1, b - a)))); };
  return {wrapStep: r3(Math.abs(loop[0] - loop[n - 1])), medianStep: r3(steps[steps.length >> 1] ?? 0), endLevelDb: lvl(n - w, n), startLevelDb: lvl(0, w)};
}

/** Inter-onset intervals (s) of a list of onset sample indices. */
const intervals = (on, sr) => on.slice(1).map((o, i) => r3((o - on[i]) / sr));

const queue = JSON.parse(fs.readFileSync(path.join(AUDIO, 'queue.json'), 'utf8'));
const manifest = {}, files = [], prov = [], qc = [];
for (const c of queue.clips) {
  const p = PLAN[c.id];
  if (!p) throw new Error(`no derivative plan for ${c.id}`);
  const side = JSON.parse(fs.readFileSync(path.join(RAW, `${c.id}.sidecar.json`), 'utf8'));
  const rawBuf = fs.readFileSync(path.join(RAW, `${c.id}.wav`));
  if (sha(rawBuf) !== side.rawSha256) throw new Error(`${c.id}: raw sha mismatch`);
  const w = readWav(rawBuf), sr = w.sampleRate;
  if (sr !== 44100) throw new Error(`${c.id}: sample rate ${sr} (the bank contract is 44.1 kHz)`);
  const mono = [D.downmix(w.channels)];
  const rawQc = qcOf(mono[0], sr);
  let chs, loop = null, ops, seam = null, extra = {};
  if (p.kind === 'oneshot') {
    chs = D.slice(mono, Math.round(p.a * sr), Math.min(mono[0].length, Math.round(p.b * sr)));
    D.fade(chs, sr, p.fadeIn, p.fadeOut);
    const g = D.normalisePeak(chs, -1);
    ops = ['mono', `trim ${p.a}-${p.b} s`, `cosine fades ${p.fadeIn} / ${p.fadeOut} s`, `peak -1 dBFS (${g.toFixed(1)} dB)`];
  } else {
    let start = p.start, len = p.len, what;
    if (p.kind === 'beatLoop') {
      const on = D.onsets(mono[0], sr, {riseDb: 6, floorDb: -30, minGapS: 0.08});
      if (on.length < p.firstBeat + p.beats + 1) throw new Error(`${c.id}: ${on.length} ticks, need ${p.firstBeat + p.beats + 1}`);
      const a = on[p.firstBeat], b = on[p.firstBeat + p.beats];
      start = r3(a / sr - p.pre);
      len = (b - a) / sr;
      // the crossfade must stay in the silence before the next tick
      if (p.xf >= p.pre) throw new Error(`${c.id}: crossfade ${p.xf} s reaches the tick (pre ${p.pre} s)`);
      const iv = intervals(on.slice(p.firstBeat, p.firstBeat + p.beats + 1), sr);
      extra = {ticks: p.beats, tickIntervalsS: iv, seamIntervalS: iv[iv.length - 1]};
      what = `beat-aligned loop: ${p.beats} tick intervals from tick ${p.firstBeat + 1} (${r3(a / sr)} s) to tick ${p.firstBeat + p.beats + 1} (${r3(b / sr)} s) = ${r3(len)} s, intervals ${iv.join(' / ')} s, start ${p.pre} s before a tick`;
    } else what = `window from ${start} s, loop ${len} s`;
    const lp = D.makeLoop(mono, sr, start, len, p.xf);
    seam = seamOf(lp[0], sr);
    chs = D.withLoopMargins(lp, sr, LOOP_MARGIN_S);
    const g = D.normaliseRms(chs, -20, -1);
    loop = {start: LOOP_MARGIN_S, length: +(lp[0].length / sr).toFixed(6)};
    ops = ['mono', what, `equal-power crossfade ${p.xf} s`, `margins ${LOOP_MARGIN_S} s`, `rms -20 dBFS, peak ceiling -1 dBFS (${g.toFixed(1)} dB)`];
  }
  const mp3 = encodeMp3(chs[0], sr, p.kbps);
  ops.push(`mp3 mono ${p.kbps} kbps`);
  const url = `assets/audio/${p.out}.mp3`;
  const dur = +(chs[0].length / sr).toFixed(4);
  (manifest[c.cue] ??= []).push({url, dur, ...(loop ? {loop} : {}), src: c.id});
  files.push({url, buf: mp3});
  const jobId = side.job?.id ?? side.jobId ?? null;
  if (!/^\d{8}T\d{6}-\d+$/.test(String(jobId))) throw new Error(`${c.id}: no Sound Lab job id in the runner sidecar`);
  prov.push({cue: c.cue, url, bytes: mp3.length, sha256: sha(mp3), dur, ...(loop ? {loop} : {}), ops,
    source: {clip: c.id, rawFile: `${RAW_REL}/raw/${c.id}.wav`, rawSha256: side.rawSha256, rawBytes: side.rawBytes,
      labFile: side.labFile, labSidecarSha256: side.labSidecarSha256, jobId, prompt: side.request.prompt, seed: side.request.seed, seconds: side.request.seconds, steps: side.request.steps, cfg: side.request.cfg}});
  qc.push({clip: c.id, cue: c.cue, url, bytes: mp3.length, raw: rawQc, derivative: qcOf(chs[0], sr), ...(seam ? {seam} : {}), ...extra});
}
for (const cue of CUES_SKYWAYS_DESTINATIONS) if (!manifest[cue]) throw new Error(`cue ${cue} has no clip`);

const total = files.reduce((s, f) => s + f.buf.length, 0);
for (const p of prov) console.log(p.cue.padEnd(14), p.url.padEnd(44), String(p.bytes).padStart(6), 'B', String(p.dur).padStart(6), 's', p.loop ? `loop ${p.loop.start}+${p.loop.length}` : 'one-shot', '|', p.ops.join(' · '));
for (const q of qc) console.log('  qc', q.cue.padEnd(14), 'raw peak', q.raw.peakDbfs, 'rms', q.raw.rmsDbfs, 'quiet', q.raw.quietFrac, 'centroid', q.raw.spectral.centroidHz, '| out peak', q.derivative.peakDbfs, 'rms', q.derivative.rmsDbfs, 'LUFS', q.derivative.loudness.integratedLufs, 'quiet', q.derivative.quietFrac, 'centroid', q.derivative.spectral.centroidHz, q.seam ? `| seam step ${q.seam.wrapStep} (median ${q.seam.medianStep}) ${q.seam.endLevelDb} -> ${q.seam.startLevelDb} dB` : '');
console.log(`total ${total} bytes (cap ${BYTE_CAP})`);
if (total > BYTE_CAP) throw new Error(`new runtime audio ${total} B exceeds the ${BYTE_CAP} B cap`);
if (DRY) process.exit(0);

// private structural QC (outside Git; the worker cannot listen)
fs.mkdirSync(path.dirname(QC_OUT), {recursive: true});
fs.writeFileSync(QC_OUT, JSON.stringify({task: TASK, lane: 'AUDIO', builtAt: new Date().toISOString(), listening: 'NOT LISTENED TO: structural analysis only; the user taste-tests in game', clips: qc}, null, 1) + '\n');

for (const f of files) fs.writeFileSync(path.join(OUT, path.basename(f.url)), f.buf);
const ts = `// GENERATED by tools/audio-pipeline/skyways-destinations-build.mjs from the Sound Lab raws — do not edit by hand.
// Provenance: public/${PROV_REL}. Task ${TASK} (lane AUDIO): the Skyways DESTINATIONS
// location sounds — the Clock Court's tick loop and bell chime, the arcade's attract loop, the cinema's projector loop
// (audio/sfx.ts setLocationEmitters).

import type {ClipRef} from './manifest.generated';

export const CLIP_MANIFEST_SKYWAYS_DESTINATIONS: Readonly<Record<string, readonly ClipRef[]>> = {
${Object.entries(manifest).map(([cue, refs]) => ` ${cue}: [\n${refs.map(r => `  ${JSON.stringify(r)},`).join('\n')}\n ],`).join('\n')}
};
/** Cues of this build without a clip (none). */
export const CLIP_GAPS_SKYWAYS_DESTINATIONS: readonly string[] = [];
/** Bytes of this build's bundled clips. */
export const CLIP_BYTES_SKYWAYS_DESTINATIONS = ${total};
`;
fs.writeFileSync(MANIFEST_TS, ts);
const provDoc = {schema: 'last-line-derivative/1', asset: 'audio-skyways-destinations-20261106', task: TASK, lane: 'AUDIO',
  generatedBy: `the existing LOCAL Sound Lab through tools/audio-pipeline/soundlab_runner.py (the task's local Sound Lab allowance; ${queue.clips.length} jobs of the plan's 4-job cap)`,
  rebuild: 'SOUND_LAB_AUDIO_DIR=<raw dir> node tools/audio-pipeline/skyways-destinations-build.mjs',
  license: {status: 'Conditional prototype status: Stability AI Community License (2024-07-05) + Gemma Terms of Use (2026-04-01). Not production or commercial clearance. "Powered by Stability AI" if distributed. Outputs may not be used to build or improve a foundational generative AI model.',
    kitStatus: 'Conditional. Not commercially cleared by this kit.', review: 'NOT LISTENED TO on the worker (no audio output): structural analysis only (per-0.1 s level, quiet fraction, spectral centroid, onsets, loop seam). The user taste-tests in game.',
    gameReady: false, approved: false, notice: 'game/public/assets/audio/NOTICE.md'},
  kbps: 64, derivatives: prov};
const provBuf = Buffer.from(JSON.stringify(provDoc, null, 1) + '\n');
{ const hit = provBuf.toString().match(/.{0,60}(https?:|Signature=|token=).{0,20}/i); if (hit) throw new Error(`URL-like string in public provenance: ...${hit[0]}...`); }
fs.writeFileSync(path.join(ROOT, 'game/public', PROV_REL), provBuf);

// NOTICE: name this set's provenance file (idempotent: replaces the sentence's tail once)
const noticePath = path.join(ROOT, 'game/public', NOTICE_REL);
let notice = fs.readFileSync(noticePath, 'utf8');
if (!notice.includes('audio-skyways-destinations.json')) {
  const tail = 'tyre skid car-skid.mp3, door car-door.mp3): ../derivatives/audio-skyways-car.json).';
  if (!notice.includes(tail)) throw new Error('NOTICE.md: expected sentence tail not found');
  notice = notice.replace(tail, 'tyre skid car-skid.mp3, door car-door.mp3): ../derivatives/audio-skyways-car.json; the Skyways destinations set (clock tick loop\nskyways-clock-tick-loop.mp3, clock chime skyways-clock-chime.mp3, arcade attract loop skyways-arcade-attract-loop.mp3, projector loop\nskyways-projector-loop.mp3): ../derivatives/audio-skyways-destinations.json).');
  fs.writeFileSync(noticePath, notice);
}
// CREDITS: one marked block (rewritten in place on a rebuild)
const creditsPath = path.join(ROOT, 'game/public', CREDITS_REL);
let credits = fs.readFileSync(creditsPath, 'utf8');
const B = '<!-- BEGIN skyways-destinations-audio-20261106 (skyways-destinations-build.mjs) -->', E = '<!-- END skyways-destinations-audio-20261106 -->';
const block = `${B}
## Skyways destinations audio (clock tick loop, clock chime, arcade attract loop, projector loop)
Generated for this project with the user's local Last Line Sound Lab CPU 0.1.0 (Stable Audio 3 Small-SFX, w8a8) under the Skyways
destinations task's local Sound Lab allowance (${queue.clips.length} jobs of a 4-job plan). Powered by Stability AI. Stability AI Community
License + Gemma Terms of Use; conditional prototype status, not production or commercial clearance. Runtime derivatives (trim, fades,
loop, levelling, MP3) built by \`tools/audio-pipeline/skyways-destinations-build.mjs\` (provenance:
\`assets/derivatives/audio-skyways-destinations.json\`). Not reviewed by ear on the build worker. Raw takes are kept outside Git.

${prov.map(p => `- \`${p.url}\` — ${p.cue} (Sound Lab job ${p.source.jobId})`).join('\n')}
${E}`;
const i0 = credits.indexOf(B), i1 = credits.indexOf(E);
credits = i0 >= 0 && i1 > i0 ? credits.slice(0, i0) + block + credits.slice(i1 + E.length) : credits.replace(/\n*$/, '\n\n') + block + '\n';
fs.writeFileSync(creditsPath, credits);

const allow = JSON.parse(fs.readFileSync(ALLOW, 'utf8'));
const mine = new Set([...files.map(f => f.url), PROV_REL, NOTICE_REL, CREDITS_REL]);
const add = [...mine].map(p => { const b = fs.readFileSync(path.join(ROOT, 'game/public', p)); return {path: p, bytes: b.length, sha256: sha(b)}; });
allow.files = [...allow.files.filter(f => !mine.has(f.path)), ...add].sort((x, y) => (x.path < y.path ? -1 : x.path > y.path ? 1 : 0));
fs.writeFileSync(ALLOW, JSON.stringify(allow, null, 2) + '\n');
console.log('wrote', files.length, 'clips +', path.relative(ROOT, MANIFEST_TS), PROV_REL, NOTICE_REL, CREDITS_REL, '+ private QC', QC_OUT);
